n-height:50px;border:1px solid #d7c89e;border-radius:8px;padding:7px}.summary{margin:0 22px 20px;padding:14px;background:#f8e7ae;border-radius:10px}.summary-line{display:flex;justify-content:space-between;padding:5px 0;gap:12px}.summary-line small{display:block;color:#6f6254}.summary-fee{border-top:1px dashed #cbbd95;margin-top:8px;padding-top:8px}.form-actions{margin:0 22px}.form-actions .button{margin-right:6px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid,.types,.delivery-fields{grid-template-columns:1fr}.tools{flex-direction:column}.form-actions{display:grid;grid-template-columns:1fr 1.3fr}.form-actions .button{margin:0}}
