<script>
const form=document.getElementById('manual-order-form'),submit=document.getElementById('submit'),summary=document.getElementById('summary'),search=document.getElementById('product-search'),filter=document.getElementById('category-filter'),tableField=document.getElementById('table-field');
const comboBeverages=@json($comboBeverages);
const money=v=>'$'+Number(v).toLocaleString('es-CO',{maximumFractionDigits:0});
function applyProductFilters(){const q=search.value.trim().toLowerCase(),category=filter.value;let visibleCount=0;document.querySelectorAll('#product-grid .card').forEach(card=>{const name=card.dataset.name||'',categoryId=String(card.dataset.category||''),categoryName=card.querySelector('.eyebrow')?.textContent?.toLowerCase()||'',matchesSearch=!q||name.includes(q)||categoryName.includes(q),matchesCategory=!category||categoryId===String(category);const visible=matchesSearch&&matchesCategory;card.hidden=!visible;if(visible)visibleCount++;});document.getElementById('products-empty').hidden=visibleCount>0;}
search.addEventListener('input',applyProductFilters);filter.addEventListener('change',applyProductFilters);
function refreshPortionTargets(){const selected=[...document.querySelectorAll('.card')].filter(c=>{const i=c.querySelector('input[data-id]');return Number(i?.value||0)>0&&c.dataset.portion!=='1';}).map(c=>({id:c.querySelector('input[data-id]').dataset.id,name:c.querySelector('h3').textContent}));document.querySelectorAll('.portion-target').forEach(s=>{const current=s.value;s.innerHTML='<option value="">Selecciona un producto</option>'+selected.map(x=>'<option value="'+x.id+'">'+x.name+'</option>').join('');s.value=current;if(s.value!==current)s.value='';});}
function refreshPortionModes(){document.querySelectorAll('.portion-mode').forEach(m=>{const id=m.dataset.portionId,wrap=document.querySelector('[data-portion-target-wrap="'+id+'"]'),target=document.querySelector('[data-portion-target="'+id+'"]'),card=m.closest('.card'),qty=Number(card?.querySelector('input[data-id]')?.value||0),active=qty>0;const pairing=m.value==='ACOMPANA';if(wrap)wrap.hidden=!active||!pairing;if(target)target.disabled=!active||!pairing;if(card){const box=card.querySelector('[data-portion-options]');if(box)box.hidden=!active;}});refreshPortionTargets();}
function refresh(){let total=0,units=0,packaging=0,lines=[];const takeaway=document.querySelector('input[name="type"][value="PARA_LLEVAR"]')?.checked;const delivery=document.querySelector('input[name="type"][value="DOMICILIO"]')?.checked;const deliveryFee=Number(document.getElementById('delivery-fee')?.value||0)||0;document.querySelectorAll('.card').forEach(c=>{const i=c.querySelector('input[data-id]'),q=Number(i.value)||0;c.classList.toggle('selected',q>0);const n=c.querySelector('.note'),o=c.querySelector('.beverage'),comboChoice=c.querySelector('.combo-choice'),comboExtra=c.querySelector('.combo-extra');if(n)n.hidden=q===0;syncSauces(c,q,takeaway||delivery);if(o)o.hidden=q===0;if(comboChoice){const comboOn=comboChoice.value==='SI';if(comboExtra)comboExtra.hidden=q===0||!comboOn;}const uo=syncUnitOptions(c,q);if(q){let price=Number(i.dataset.price),detail='';if(i.dataset.juice==='1'){const prep=c.querySelector('[name^="juice_preparation"]')?.value||'AGUA';price=prep==='LECHE'?9500:8500;const f=c.querySelector('[name^="juice_fruit"]')?.selectedOptions[0]?.text||'';detail=(prep==='LECHE'?'En leche':'En agua')+' · '+f}else if(comboChoice?.value==='SI'){const type=c.querySelector('[data-combo-type]')?.selectedOptions[0]?.text||'';const flavor=c.querySelector('[data-combo-flavor]')?.value||'';price+=10000;detail=`COMBO +$10.000 · Papas a la francesa · ${type} · ${flavor}`;}else{const s=c.querySelector('.beverage select');detail=s?.value||''}if(uo)detail='';const line=uo?uo.total:q*price;const fee=(takeaway||delivery)&&c.dataset.packaging==='1'?1500*q:0;total+=line;packaging+=fee;units+=q;lines.push(`<div class="summary-line"><span>${q} × ${i.closest('.card').querySelector('h3').textContent}<small>${detail}</small>${uo?uo.html:''}${sauceSummaryHtml(c)}</span><strong>${money(line)}</strong></div>`)}});document.getElementById('items-count').textContent=`${units} producto${units===1?'':'s'} seleccionado${units===1?'':'s'}`;const feeLine=(takeaway||delivery)&&packaging?`<div class="summary-line summary-fee"><span>Empaques para llevar</span><strong>${money(packaging)}</strong></div>`:'';summary.innerHTML=lines.length?lines.join('')+generalSaucesSummaryHtml(takeaway||delivery)+feeLine+`<div class="summary-line"><strong>Total</strong><strong>${money(total+packaging+(delivery?deliveryFee:0))}</strong></div>`:'Agrega productos para ver el resumen.';submit.disabled=units===0;const gs=document.querySelector('[data-general-sauces]');if(gs){const showGeneral=takeaway||delivery;gs.hidden=!showGeneral;gs.querySelectorAll('input').forEach(i=>i.disabled=!showGeneral);}}
document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{const i=document.querySelector(`input[data-id="${b.dataset.plus}"]`);i.value=Math.min(99,Number(i.value)+1);refresh();refreshPortionModes()});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const i=document.querySelector(`input[data-id="${b.dataset.minus}"]`);i.value=Math.max(0,Number(i.value)-1);refresh();refreshPortionModes()});document.querySelectorAll('.beverage select,.juice select,.combo-choice,[data-combo-type],[data-combo-flavor]').forEach(s=>s.addEventListener('change',()=>{if(s.matches('.combo-choice')){const id=s.dataset.id,extra=document.querySelector(`[data-combo-extra="${id}"]`);if(extra)extra.hidden=s.value!=='SI';}if(s.matches('[data-combo-type]')){const id=s.getAttribute('data-combo-type'),flavor=document.querySelector(`[data-combo-flavor="${id}"]`),flavors=comboBeverages[s.value]?.flavors||[];if(flavor)flavor.innerHTML=flavors.map(value=>`<option value="${value}">${value}</option>`).join('');}refresh();}));document.querySelectorAll('.card .note textarea').forEach(t=>t.addEventListener('input',refresh));document.querySelectorAll('.portion-mode').forEach(s=>s.addEventListener('change',refreshPortionModes));document.querySelectorAll('.portion-target').forEach(s=>s.addEventListener('change',refresh));document.querySelectorAll('input[name="type"]').forEach(r=>r.addEventListener('change',()=>{const isTable=r.value==='MESA'&&r.checked;const isDelivery=r.value==='DOMICILIO'&&r.checked;tableField.style.display=isTable?'block':'none';document.getElementById('delivery-fields').hidden=!isDelivery;refresh()}));document.getElementById('delivery-fee').addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'');refresh()});const initialType=document.querySelector('input[name="type"]:checked')?.value;tableField.style.display=initialType==='MESA'?'block':'none';document.getElementById('delivery-fields').hidden=initialType!=='DOMICILIO';refresh();applyProductFilters();refreshPortionModes();form.addEventListener('change',e=>{if(e.target.closest('[data-sauce-picker],[data-general-sauces]')||e.target.matches('[data-option-mode]'))refresh();});
</script>
@endsection
